using System;
using System.Linq;
using NUnit.Framework;
using LegendsOfRus.GameplayCore;
namespace LegendsOfRus.Tests
{
    public class RunicSealTests
    {
        static BoardPosition P(int x,int y)=>new BoardPosition(x,y);
        static BoardModel Board(){var b=new BoardModel(8,7,6,new SeededBoardRandom(1)){SquareMatches=true};for(int y=0;y<7;y++)for(int x=0;x<8;x++)b.SetCell(P(x,y),new BoardCellData((x+2*y)%6));b.SetObstacle(P(5,3),new BoardObstacleData(BoardObstacleKind.RunicSeal,2));return b;}
        static BoardResolutionPlanner Planner(BoardModel b)=>new BoardResolutionPlanner(b,null,GameplayRuleVersion.PrototypeR3);
        [Test] public void LayersAndOccupancyAreValidated(){Assert.Throws<ArgumentOutOfRangeException>(()=>new BoardObstacleData(BoardObstacleKind.RunicSeal,3));Assert.Throws<ArgumentOutOfRangeException>(()=>new BoardObstacleData(BoardObstacleKind.RunicSeal,0));var b=Board();Assert.That(b.GetCell(P(5,3)).IsEmpty,Is.True);Assert.That(b.CanSwap(P(5,3),P(4,3)),Is.False);Assert.Throws<InvalidOperationException>(()=>b.SetCell(P(5,3),new BoardCellData(1)));Assert.Throws<InvalidOperationException>(()=>b.SetObjectiveItem(P(5,3),BoardObjectiveItemKind.FirebirdFeather));}
        [TestCase(GameplayRuleVersion.Legacy)][TestCase(GameplayRuleVersion.PrototypeR1)][TestCase(GameplayRuleVersion.PrototypeR2)] public void OlderProfilesRejectSeals(GameplayRuleVersion rules){Assert.Throws<ArgumentException>(()=>new BoardResolutionPlanner(Board(),null,rules));}
        [Test] public void AdjacentMatchIsImmune(){var b=Board();b.ClearObstacle(P(5,3));b.SetObstacle(P(4,2),new BoardObstacleData(BoardObstacleKind.RunicSeal,2));for(int x=1;x<=3;x++)b.SetCell(P(x,2),new BoardCellData(x==3?3:2));b.SetCell(P(3,3),new BoardCellData(2));var p=Planner(b).PlanSwap(P(3,3),P(3,2));Assert.That(p.IsResolved,Is.True);Assert.That(p.Waves.SelectMany(w=>w.ObstacleInteractions),Is.Empty);Assert.That(p.FinalSnapshot.ObstacleLayers[20],Is.EqualTo(2));}
        [TestCase(SpecialGemKind.Row,3,3)][TestCase(SpecialGemKind.Column,5,1)][TestCase(SpecialGemKind.Burst,3,3)][TestCase(SpecialGemKind.Spark,3,3)]
        public void DirectSpecialRemovesOneLayer(SpecialGemKind kind,int x,int y){var b=Board();b.SetCell(P(x,y),new BoardCellData(1,kind));string before=b.ComputeStateHash();var p=Planner(b).PlanTapSpecial(P(x,y));Assert.That(p.IsResolved,Is.True);var hit=p.Waves[0].ObstacleInteractions.Single(h=>h.Kind==BoardObstacleKind.RunicSeal);Assert.That(hit.LayersAfter,Is.EqualTo(1));Assert.That(hit.Destroyed,Is.False);Assert.That(b.ComputeStateHash(),Is.EqualTo(before));Assert.That(Planner(b).PlanTapSpecial(P(x,y)).PlanHash,Is.EqualTo(p.PlanHash));}
        [Test] public void OverlappingCombinationHitsOnce(){var b=Board();b.SetCell(P(3,3),new BoardCellData(1,SpecialGemKind.Row));b.SetCell(P(4,3),new BoardCellData(2,SpecialGemKind.Burst));var w=Planner(b).PlanSwap(P(3,3),P(4,3)).Waves[0];Assert.That(w.ObstacleInteractions.Count(h=>h.Kind==BoardObstacleKind.RunicSeal),Is.EqualTo(1));Assert.That(w.ObstacleInteractions.Single(h=>h.Kind==BoardObstacleKind.RunicSeal).LayersAfter,Is.EqualTo(1));}
        [TestCase(BoardBoosterCommandKind.MaceRow)][TestCase(BoardBoosterCommandKind.MaceColumn)][TestCase(BoardBoosterCommandKind.FirebirdArea)]
        public void BoosterCanTargetSealAndFinalHitDestroys(BoardBoosterCommandKind kind){var b=Board();var p=Planner(b).PlanBooster(new BoardBoosterRequest(kind,P(5,3)));Assert.That(p.IsResolved,Is.True);Assert.That(p.ConsumesMove,Is.False);Assert.That(p.Waves[0].ObstacleInteractions.Single().LayersAfter,Is.EqualTo(1));b.RestoreSnapshot(p.FinalSnapshot);p=Planner(b).PlanBooster(new BoardBoosterRequest(kind,P(5,3)));Assert.That(p.Waves[0].ObstacleInteractions.Single().Destroyed,Is.True);Assert.That(p.FinalSnapshot.Obstacles[29],Is.EqualTo(BoardObstacleKind.None));}
        [Test] public void ColorClearDoesNotDamageSeal(){var b=Board();Assert.That(Planner(b).PlanBooster(new BoardBoosterRequest(BoardBoosterCommandKind.LivingLightColor,P(5,3))).IsResolved,Is.False);var p=Planner(b).PlanBooster(new BoardBoosterRequest(BoardBoosterCommandKind.LivingLightColor,P(0,0)));Assert.That(p.Waves.SelectMany(w=>w.ObstacleInteractions),Is.Empty);}
        [Test] public void ReplayPreservesSealAndLayers(){var b=Board();var token=b.CreateSnapshot().ToReplayToken();var snap=BoardReplayCodec.Decode(token);Assert.That(snap.Obstacles[29],Is.EqualTo(BoardObstacleKind.RunicSeal));Assert.That(snap.ObstacleLayers[29],Is.EqualTo(2));b.RestoreSnapshot(snap);Assert.That(b.CreateSnapshot().ToReplayToken(),Is.EqualTo(token));Assert.Throws<FormatException>(()=>BoardReplayCodec.Decode(token.Replace("-1/0/4/2/0","-1/0/4/3/0")));}
        [Test] public void GravityStopsAtSealAndResumesAfterRemoval(){var b=new BoardModel(3,5,4,new SequenceBoardRandom(0,1,2,3));b.LoadRows(".1.","...","...",".2.","...");b.SetObstacle(P(1,2),new BoardObstacleData(BoardObstacleKind.RunicSeal,2));var c=b.CollapseAndRefill();Assert.That(b.GetTile(P(1,4)),Is.EqualTo(2));Assert.That(b.GetCell(P(1,3)).IsEmpty,Is.True);Assert.That(c.Spawns.Any(s=>s.To.X==1&&s.To.Y>2),Is.False);b.ClearObstacle(P(1,2));b.CollapseAndRefill();Assert.That(b.GetCell(P(1,3)).IsEmpty,Is.False);}
        [Test] public void RecoveryPreservesSeal(){var b=Board();b.EnsurePlayableBoard();Assert.That(b.GetObstacle(P(5,3)).Layers,Is.EqualTo(2));Assert.That(b.GetCell(P(5,3)).IsEmpty,Is.True);Assert.That(b.HasLegalMove(),Is.True);}
    }
}
